head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.fn_SetPar;
scwin.gBzTyp = '';
scwin.vScrenID = 'ULDSTF37703.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_resizeToWin = function() {
    frame.Width = 330;
    frame.Height = 330;
};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_list_sync = function() {
    var url = '';
    url = "/ConfrmProcs.do?method=listDesignRsn";
    url += "&CD_ENG_NM=CPOC_DESIGN_RSN_CD";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_rsn.DataID = encodeURI(url);
    dts_rsn.Reset();
};
scwin.setValue = async function() {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = dts_rsn.getCellData(dts_rsn.getRowPosition(), 2);
        arrPar[1] = dts_rsn.getCellData(dts_rsn.getRowPosition(), 3);
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.grd_rsn_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.grd_rsn_OnDblClick = function(row, colid) {
    scwin.setValue();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_resizeToWin();
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    scwin.fn_list_sync();
};
